var input = $input.first().json;
var OWNER = input.githubOwner || 'bisco401';
var REPO = input.githubRepo || '6ixo';
var BRANCH = input.githubBranch || 'main';
var CSV_PATH = input.csvPath || 'data/scraped-listings.csv';
var TOKEN = input.githubToken;
var MAX_ROWS = Math.max(1, Number(input.maxRowsPerRun || 150));
var REQUEST_DELAY_MS = Math.max(0, Number(input.requestDelayMs || 1200));
var RECHECK_AFTER_HOURS = Math.max(0, Number(input.recheckAfterHours || 24));
var HIDE_UNAVAILABLE = String(input.hideUnavailableListings || 'false').toLowerCase() === 'true';
var DELETE_UNAVAILABLE = String(input.deleteUnavailableListings || 'true').toLowerCase() === 'true';
var CONFIRMED_UNAVAILABLE = ['sold', 'unavailable', 'gone'];
var SOURCE_BASE_URLS = {};

try {
  SOURCE_BASE_URLS = typeof input.sourceBaseUrlsJson === 'string' ? JSON.parse(input.sourceBaseUrlsJson || '{}') : (input.sourceBaseUrlsJson || {});
} catch (error) {
  throw new Error('sourceBaseUrlsJson is not valid JSON.');
}

if (!TOKEN || TOKEN === 'PASTE_GITHUB_TOKEN_HERE') {
  throw new Error('Set GITHUB_TOKEN in the n8n environment before running this workflow.');
}

var ghHeaders = {
  authorization: 'Bearer ' + TOKEN,
  accept: 'application/vnd.github+json',
  'x-github-api-version': '2022-11-28'
};
var checkHeaders = {
  'user-agent': '6ixo-listing-availability-check/1.0 (+https://6ixo.com)',
  'accept-language': 'en-US,en;q=0.9'
};
var addedHeaders = [
  'source_availability',
  'source_availability_checked_at',
  'source_http_status',
  'source_unavailable_reason',
  'source_last_seen_at',
  'source_resolved_url'
];

function sleep(ms) {
  return new Promise(function(resolve) { setTimeout(resolve, ms); });
}

async function httpRequest(options) {
  var request = {
    method: options.method || 'GET',
    uri: options.url,
    url: options.url,
    headers: options.headers || {},
    body: options.body,
    json: options.json === true,
    resolveWithFullResponse: true,
    simple: false,
    followRedirect: true,
    timeout: options.timeout || 45000
  };
  try {
    var response = await this.helpers.httpRequest(request);
    var status = response.statusCode || response.status || 200;
    var body = response.body == null ? response : response.body;
    return {
      status: status,
      ok: status >= 200 && status < 300,
      body: body,
      headers: response.headers || {}
    };
  } catch (error) {
    var errorResponse = error.response || {};
    var errorStatus = error.statusCode || error.status || errorResponse.status || errorResponse.statusCode || 500;
    var errorBody = errorResponse.body || errorResponse.data || error.message || '';
    return {
      status: errorStatus,
      ok: errorStatus >= 200 && errorStatus < 300,
      body: errorBody,
      headers: errorResponse.headers || {}
    };
  }
}

function csvEscape(value) {
  var text = String(value == null ? '' : value);
  var mustQuote = text.indexOf('"') >= 0 || text.indexOf(',') >= 0 || text.indexOf(String.fromCharCode(10)) >= 0 || text.indexOf(String.fromCharCode(13)) >= 0;
  return mustQuote ? '"' + text.split('"').join('""') + '"' : text;
}

function parseCsvWithHeaders(text) {
  var rows = [];
  var row = [];
  var cell = '';
  var quoted = false;
  var inputText = String(text || '');
  if (inputText.charCodeAt(0) === 65279) inputText = inputText.slice(1);

  function pushCell() {
    row.push(cell);
    cell = '';
  }
  function pushRow() {
    pushCell();
    var hasValue = false;
    for (var r = 0; r < row.length; r += 1) {
      if (String(row[r] || '').trim()) hasValue = true;
    }
    if (hasValue) rows.push(row);
    row = [];
  }

  for (var i = 0; i < inputText.length; i += 1) {
    var char = inputText[i];
    var next = inputText[i + 1];
    if (quoted) {
      if (char === '"' && next === '"') {
        cell += '"';
        i += 1;
      } else if (char === '"') {
        quoted = false;
      } else {
        cell += char;
      }
    } else if (char === '"') {
      quoted = true;
    } else if (char === ',') {
      pushCell();
    } else if (char.charCodeAt(0) === 10) {
      pushRow();
    } else if (char.charCodeAt(0) !== 13) {
      cell += char;
    }
  }
  if (cell || row.length) pushRow();

  var headers = rows.shift() || [];
  var cleanHeaders = [];
  for (var h = 0; h < headers.length; h += 1) {
    var header = String(headers[h] || '').trim();
    if (header) cleanHeaders.push(header);
  }
  var records = [];
  for (var rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    var record = {};
    for (var colIndex = 0; colIndex < cleanHeaders.length; colIndex += 1) {
      record[cleanHeaders[colIndex]] = rows[rowIndex][colIndex] || '';
    }
    records.push(record);
  }
  return { headers: cleanHeaders, records: records };
}

function toCsv(headers, rows) {
  var outputHeaders = headers.slice();
  for (var i = 0; i < addedHeaders.length; i += 1) {
    if (outputHeaders.indexOf(addedHeaders[i]) < 0) outputHeaders.push(addedHeaders[i]);
  }
  var lines = [outputHeaders.join(',')];
  for (var rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    var row = rows[rowIndex];
    var cells = [];
    for (var colIndex = 0; colIndex < outputHeaders.length; colIndex += 1) {
      cells.push(csvEscape(row[outputHeaders[colIndex]] || ''));
    }
    lines.push(cells.join(','));
  }
  return lines.join(String.fromCharCode(10)) + String.fromCharCode(10);
}

async function getGithubCsv() {
  var url = 'https://api.github.com/repos/' + OWNER + '/' + REPO + '/contents/' + encodeURIComponent(CSV_PATH).split('%2F').join('/') + '?ref=' + BRANCH;
  var res = await httpRequest.call(this, { url: url, headers: ghHeaders, json: true });
  if (res.status === 404) throw new Error(CSV_PATH + ' was not found in ' + OWNER + '/' + REPO + '@' + BRANCH + '.');
  if (!res.ok) throw new Error('Could not read ' + CSV_PATH + ': ' + res.status + ' ' + (typeof res.body === 'string' ? res.body : JSON.stringify(res.body)));
  var metadata = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  if (!metadata || !metadata.sha) throw new Error('GitHub did not return a CSV blob SHA.');
  var encoded = String(metadata.content || '').split('\n').join('');
  if (!encoded || String(metadata.encoding || '').toLowerCase() !== 'base64') {
    var blob = await httpRequest.call(this, {
      url: 'https://api.github.com/repos/' + OWNER + '/' + REPO + '/git/blobs/' + metadata.sha,
      headers: ghHeaders,
      json: true
    });
    if (!blob.ok) throw new Error('Could not read ' + CSV_PATH + ' blob: ' + blob.status + '.');
    var blobBody = typeof blob.body === 'string' ? JSON.parse(blob.body) : blob.body;
    encoded = String((blobBody && blobBody.content) || '').split('\n').join('');
  }
  if (!encoded) throw new Error('GitHub returned an empty CSV blob; refusing to overwrite existing listings.');
  var text = Buffer.from(encoded, 'base64').toString('utf8');
  if (!text.trim()) throw new Error('GitHub returned an empty CSV; refusing to overwrite existing listings.');
  return { sha: metadata.sha, text: text };
}
async function putGithubCsv(text, sha) {
  var url = 'https://api.github.com/repos/' + OWNER + '/' + REPO + '/contents/' + encodeURIComponent(CSV_PATH).split('%2F').join('/');
  var body = {
    message: 'Remove sold or unavailable scraped listings',
    branch: BRANCH,
    content: Buffer.from(text, 'utf8').toString('base64')
  };
  if (sha) body.sha = sha;
  var res = await httpRequest.call(this, { url: url, method: 'PUT', headers: Object.assign({}, ghHeaders, { 'content-type': 'application/json' }), body: body, json: true });
  if (!res.ok) {
    var updateBody = typeof res.body === 'string' ? res.body : JSON.stringify(res.body);
    if (res.status === 403 && updateBody.indexOf('Resource not accessible by personal access token') >= 0) {
      throw new Error('GitHub token can read the CSV but cannot write it. Edit or recreate the fine-grained token with Repository permissions > Contents = Read and write for ' + OWNER + '/' + REPO + '.');
    }
    throw new Error('Could not update ' + CSV_PATH + ': ' + res.status + ' ' + updateBody);
  }
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
}

function parseAttributes(value) {
  try {
    return JSON.parse(String(value || '').trim() || '{}') || {};
  } catch (error) {
    return {};
  }
}

function inferBaseUrl(row) {
  var sourceText = String((row.source_site || '') + ' ' + (row.source_url || '') + ' ' + (row.id || '') + ' ' + (row.attributes || '')).toLowerCase();
  var keys = Object.keys(SOURCE_BASE_URLS || {});
  for (var i = 0; i < keys.length; i += 1) {
    var key = keys[i];
    if (key && sourceText.indexOf(String(key).toLowerCase()) >= 0) return String(SOURCE_BASE_URLS[key] || '').replace(new RegExp('/$'), '');
  }
  var attributes = parseAttributes(row.attributes);
  var parser = String(attributes.parser || '').toLowerCase();
  if (parser && SOURCE_BASE_URLS[parser]) return String(SOURCE_BASE_URLS[parser]).replace(new RegExp('/$'), '');
  return '';
}

function resolveSourceUrl(row) {
  var raw = String(row.source_url || row.url || '').trim();
  if (!raw) return '';
  try {
    return new URL(raw).toString();
  } catch (error) {}
  var base = inferBaseUrl(row);
  if (!base) return raw;
  try {
    return new URL(raw, base).toString();
  } catch (error) {
    return raw;
  }
}

function compactText(value) {
  var text = String(value || '');
  text = text.replace(new RegExp('<script[\\s\\S]*?</script>', 'gi'), ' ');
  text = text.replace(new RegExp('<style[\\s\\S]*?</style>', 'gi'), ' ');
  text = text.replace(new RegExp('<[^>]+>', 'g'), ' ');
  text = text.split('&nbsp;').join(' ');
  text = text.split('&amp;').join('&');
  text = text.replace(new RegExp('\\s+', 'g'), ' ');
  return text.trim();
}

function significantTitleWords(title) {
  var cleaned = String(title || '').toLowerCase().replace(new RegExp('[^a-z0-9 ]+', 'g'), ' ');
  var parts = cleaned.split(new RegExp('\\s+'));
  var blocked = { with: true, sale: true, used: true, good: true, price: true, call: true, contact: true };
  var words = [];
  for (var i = 0; i < parts.length; i += 1) {
    var word = parts[i];
    if (word.length >= 4 && !blocked[word]) words.push(word);
    if (words.length >= 5) break;
  }
  return words;
}

function titleStillMatches(row, text) {
  var words = significantTitleWords(row.title || '');
  if (!words.length) return true;
  var lower = String(text || '').toLowerCase();
  for (var i = 0; i < words.length; i += 1) {
    if (lower.indexOf(words[i]) >= 0) return true;
  }
  return false;
}

function containsAny(text, phrases) {
  var lower = String(text || '').toLowerCase();
  for (var i = 0; i < phrases.length; i += 1) {
    if (lower.indexOf(phrases[i]) >= 0) return true;
  }
  return false;
}

function classifyAvailability(row, status, body) {
  var html = typeof body === 'string' ? body : JSON.stringify(body || '');
  var text = compactText(html).slice(0, 250000);
  var lowerHtml = html.toLowerCase();
  if (status === 404 || status === 410) return { availability: 'gone', reason: 'HTTP ' + status };
  if (status === 401 || status === 403 || status === 429) return { availability: 'unknown', reason: 'Blocked or rate limited: HTTP ' + status };
  if (status >= 500) return { availability: 'unknown', reason: 'Temporary source error: HTTP ' + status };
  if (containsAny(lowerHtml, ['just a moment', 'cf-mitigated', 'challenges.cloudflare.com', 'captcha', 'access denied', 'unusual traffic'])) {
    return { availability: 'unknown', reason: 'Blocked by anti-bot or captcha page' };
  }
  if (containsAny(text, ['marked as sold', 'item has sold', 'item is sold', 'this item sold', 'this ad has been sold', 'sold out'])) {
    return { availability: 'sold', reason: 'Source page says sold' };
  }
  if (containsAny(text, ['this ad is no longer available', 'this listing is no longer available', 'listing no longer available', 'ad no longer available', 'no longer available', 'has expired', 'listing expired', 'ad expired', 'removed by the seller', 'listing removed', 'ad removed', 'deleted by the seller', 'not found'])) {
    return { availability: 'unavailable', reason: 'Source page says unavailable or removed' };
  }
  if (!status || status < 200 || status >= 400) return { availability: 'unknown', reason: 'Unexpected HTTP ' + (status || 'unknown') };
  if (!titleStillMatches(row, text)) return { availability: 'unknown', reason: 'Page loaded but title did not clearly match listing' };
  return { availability: 'active', reason: 'Detail page still loads' };
}

function shouldCheckRow(row) {
  var sourceUrl = String(row.source_url || row.url || '').trim();
  if (!sourceUrl) return false;
  if (RECHECK_AFTER_HOURS <= 0) return true;
  var checkedAt = Date.parse(row.source_availability_checked_at || '');
  if (!Number.isFinite(checkedAt)) return true;
  return checkedAt <= Date.now() - (RECHECK_AFTER_HOURS * 60 * 60 * 1000);
}

var existing = await getGithubCsv.call(this);
var parsed = parseCsvWithHeaders(existing.text);
var records = parsed.records;
var candidates = [];
for (var i = 0; i < records.length; i += 1) {
  if (shouldCheckRow(records[i])) candidates.push(records[i]);
  if (candidates.length >= MAX_ROWS) break;
}

var checkedAt = new Date().toISOString();
var counts = { active: 0, sold: 0, unavailable: 0, gone: 0, unknown: 0, checked: 0 };
for (var c = 0; c < candidates.length; c += 1) {
  var row = candidates[c];
  var resolvedUrl = resolveSourceUrl(row);
  row.source_resolved_url = resolvedUrl;
  row.source_availability_checked_at = checkedAt;
  if (!resolvedUrl || resolvedUrl.toLowerCase().indexOf('http') !== 0) {
    row.source_availability = 'unknown';
    row.source_http_status = '';
    row.source_unavailable_reason = 'Could not resolve source URL';
    counts.unknown += 1;
    counts.checked += 1;
    continue;
  }
  if (REQUEST_DELAY_MS) await sleep(REQUEST_DELAY_MS);
  var response = await httpRequest.call(this, { url: resolvedUrl, headers: checkHeaders, timeout: 45000 });
  var result = classifyAvailability(row, response.status, response.body);
  row.source_availability = result.availability;
  row.source_http_status = String(response.status || '');
  row.source_unavailable_reason = result.reason;
  if (result.availability === 'active') row.source_last_seen_at = checkedAt;
  if (!DELETE_UNAVAILABLE && HIDE_UNAVAILABLE && CONFIRMED_UNAVAILABLE.indexOf(result.availability) >= 0) row.status = 'rejected';
  if (counts[result.availability] == null) counts.unknown += 1;
  else counts[result.availability] += 1;
  counts.checked += 1;
}

var totalRowsBeforeDelete = records.length;
var deletedListingIds = [];
if (DELETE_UNAVAILABLE) {
  records = records.filter(function(row) {
    var availability = String(row.source_availability || '').trim().toLowerCase();
    if (CONFIRMED_UNAVAILABLE.indexOf(availability) < 0) return true;
    deletedListingIds.push(String(row.id || row.source_url || ''));
    return false;
  });
}

await putGithubCsv.call(this, toCsv(parsed.headers, records), existing.sha);
return [{ json: {
  checked: counts.checked,
  totalRowsBeforeDelete: totalRowsBeforeDelete,
  totalRows: records.length,
  deleted: deletedListingIds.length,
  deletedListingIds: deletedListingIds,
  active: counts.active,
  sold: counts.sold,
  unavailable: counts.unavailable,
  gone: counts.gone,
  unknown: counts.unknown,
  hideUnavailableListings: HIDE_UNAVAILABLE,
  deleteUnavailableListings: DELETE_UNAVAILABLE,
  csvPath: CSV_PATH
} }];
